func (m *Management) GetRun(ctx context.Context, creq *connect.Request[managementv1.GetRunRequest]) (*connect.Response[managementv1.GetRunResponse], error) {
	req := creq.Msg
	b, err := m.allow(ctx, authz.VerbGet, authz.KindRun)
	if err != nil {
		return nil, err
	}
	desc, err := b.Client.DescribeWorkflowExecution(ctx, "run/"+req.GetRunId(), "")
	if err != nil {
		return nil, status.Error(codes.NotFound, err.Error())
	}
	return connect.NewResponse(&managementv1.GetRunResponse{
		Status: selector.RunPhase(desc.GetWorkflowExecutionInfo().GetStatus()),
	}), nil
}

// RunStatus reports the run's in-flight state — the pending activities
// it is waiting on, with attempt count, last failure and latest
// heartbeat note. This is the "what is it doing / why is it stuck" view,
// read straight from the workflow's pending-activity state so no Temporal
// CLI is needed to answer it.

